class AbTest(TypedDict, total=False):
    """Always present: `id`, `pageId`, `enabled`, `status`, `variantA`, `variantB`, `trafficSplit`, `primaryGoal`, `customGoalEvent`, `minSampleSize`, `confidenceLevel`, `startDate`, `endDate`, `winningVariant`, `createdBy`, `live`, `proposal`, `decision`, `createdAt`, `updatedAt`.
    """
    id: str
    pageId: str
    enabled: bool
    status: Optional[str]
    """`draft`, `running`, `paused`, `completed` or `decided`."""
    variantA: Dict[str, Any]
    variantB: Dict[str, Any]
    trafficSplit: Optional[float]
    """Percent of visitors shown variant B."""
    primaryGoal: Optional[str]
    customGoalEvent: Optional[str]
    minSampleSize: Optional[float]
    confidenceLevel: Optional[float]
    startDate: Optional[str]
    endDate: Optional[str]
    winningVariant: Optional[str]
    createdBy: Optional[str]
    live: Optional[Dict[str, Any]]
    """What visitors are served while the test runs on the live site; set only through the page's A/B actions."""
    proposal: Optional[Dict[str, Any]]
    """A start or update waiting for approval."""
    decision: Optional[Dict[str, Any]]
    createdAt: str
    updatedAt: str


class AbTestsCreateResponse(TypedDict, total=False):
    """Always present: `success`, `data`.
    """
